    if (obj.payload != null) { w.writeField("payload"); w.writeBytes(obj.payload) }
    w.endObject()
}

val TimestampEntryCodec: SpecCodec<TimestampEntry> = SpecCodec(
    encode = { w, obj -> _writeTimestampEntry(w, obj) },
    decode = { r ->
        var _ts: Long = 0L
        var _event: String = ""
        var _payload: ByteArray? = null
        r.beginObject()
        while (r.hasNextField()) {
            when (r.readFieldName()) {
                "ts" -> _ts = r.readInt64()
                "event" -> _event = r.readString()
                "payload" -> _payload = r.readBytes()
                else -> r.skip()
            }
        }
        r.endObject()
        TimestampEntry(ts = _ts, event = _event, payload = _payload)
    }
)

data class ConfigEntry(
    val key: String,
    val intValue: Int? = null,
    val strValue: String? = null,
    val boolValue: Boolean? = null,
    val floatValue: Double? = null,
)

private fun _writeConfigEntry(w: SpecWriter, obj: ConfigEntry) {
    var _n = 1
    if (obj.intValue != null) _n++
    if (obj.strValue != null) _n++
    if (obj.boolValue != null) _n++
    if (obj.floatValue != null) _n++
    w.beginObject(_n)
    w.writeField("key"); w.writeString(obj.key)
    if (obj.intValue != null) { w.writeField("intValue"); w.writeInt32(obj.intValue) }
    if (obj.strValue != null) { w.writeField("strValue"); w.writeString(obj.strValue) }
    if (obj.boolValue != null) { w.writeField("boolValue"); w.writeBool(obj.boolValue) }
    if (obj.floatValue != null) { w.writeField("floatValue"); w.writeFloat64(obj.floatValue) }
    w.endObject()
}

val ConfigEntryCodec: SpecCodec<ConfigEntry> = SpecCodec(
    encode = { w, obj -> _writeConfigEntry(w, obj) },
    decode = { r ->
        var _key: String = ""
        var _intValue: Int? = null
        var _strValue: String? = null
        var _boolValue: Boolean? = null
        var _floatValue: Double? = null
        r.beginObject()
        while (r.hasNextField()) {
            when (r.readFieldName()) {
                "key" -> _key = r.readString()
                "intValue" -> _intValue = r.readInt32()
                "strValue" -> _strValue = r.readString()
                "boolValue" -> _boolValue = r.readBool()
                "floatValue" -> _floatValue = r.readFloat64()
                else -> r.skip()
            }
        }
        r.endObject()
        ConfigEntry(key = _key, intValue = _intValue, strValue = _strValue, boolValue = _boolValue, floatValue = _floatValue)
    }
)
